      '## ภาพรวม\n\nเซนเซอร์วัดอุณหภูมิและความชื้นที่รวมตัวตรวจจับกับวงจรแปลงสัญญาณไว้ในตัวถังเดียว ส่งค่าที่\nแปลงเป็นตัวเลขแล้วกลับมาทางสายสัญญาณเส้นเดียว จึงไม่ต้องใช้ขาแอนะล็อกและไม่ต้องปรับเทียบ\n\n## เปรียบเทียบสองรุ่น\n\n| หัวข้อ | DHT11 | DHT22 |\n| --- | --- | --- |\n| ช่วงวัดอุณหภูมิ | 0 ถึง 50 °C | −40 ถึง 80 °C |\n| ความคลาดเคลื่อน | ±2 °C | ±0.5 °C |\n| ความละเอียด | 1 °C | 0.1 °C |\n| ช่วงวัดความชื้น | 20–90 %RH | 0–100 %RH |\n| ความคลาดเคลื่อนความชื้น | ±5 %RH | ±2 %RH |\n| อ่านค่าได้ถี่สุด | 1 ครั้งต่อ 1 วินาที | 1 ครั้งต่อ 2 วินาที |\n| สีตัวถัง | ฟ้า | ขาว |\n\nDHT11 วัดอุณหภูมิติดลบไม่ได้เลย งานที่ต้องวัดในตู้เย็นหรือกลางแจ้งหน้าหนาวต้องใช้ DHT22\n\n## การต่อวงจร\n\nตัวเซนเซอร์แบบสี่ขา ขาที่สามนับจากซ้ายไม่ได้ต่ออะไรภายใน ปล่อยลอยไว้\n\n```\nDHT          บอร์ด\nVCC   ────   3V3 หรือ 5V\nDATA  ────   GPIO ที่เลือก\nNC           ไม่ต่อ\nGND   ────   GND\n```\n\n**ต้องมีตัวต้านทานพูลอัป 4.7 kΩ ระหว่างขา DATA กับ VCC เสมอ** บอร์ดแบบสามขาที่ขายกันทั่วไป\nมีตัวต้านทานนี้ติดมาบนแผ่นแล้ว ถ้าใช้ตัวเซนเซอร์เปล่าต้องต่อเอง ไม่มีตัวนี้แล้วจะอ่านค่าไม่ได้เลย\nหรือได้ค่าขยะสลับกับค่าถูกต้อง\n\n## ตัวอย่างโค้ด\n\n```cpp\n#include <DHT.h>\n\n#define DHT_PIN 4\nDHT dht(DHT_PIN, DHT22);\n\nunsigned long lastRead = 0;\nfloat temperature = NAN;\nfloat humidity = NAN;\n\nvoid setup() {\n  Serial.begin(115200);\n  dht.begin();\n}\n\nvoid loop() {\n  if (millis() - lastRead >= 2000) {\n    lastRead = millis();\n    float t = dht.readTemperature();\n    float h = dht.readHumidity();\n    if (isnan(t) || isnan(h)) {\n      Serial.println("อ่านค่าไม่สำเร็จ");\n      return;\n    }\n    temperature = t;\n    humidity = h;\n  }\n}\n```\n\nต้องตรวจ `isnan` ทุกครั้ง ไลบรารีคืนค่า `NAN` เมื่ออ่านไม่สำเร็จ ถ้าเอาค่าไปคำนวณต่อโดยไม่ตรวจ\nผลลัพธ์ทั้งสายจะกลายเป็น `NAN` ตามไปด้วย\n\n## ปัญหาที่พบบ่อย\n\n- **อ่านได้ `NAN` ตลอด** ไม่มีตัวต้านทานพูลอัป หรือสายยาวเกิน 20 เมตร\n- **ค่าถูกสลับกับค่าขยะ** อ่านถี่เกินกำหนด ให้เว้นระยะตามตารางข้างบน\n- **อุณหภูมิสูงกว่าความจริง 2–3 °C** เซนเซอร์อยู่ใกล้ตัวควบคุมแรงดันของบอร์ดที่ร้อน ให้ย้าย\n  ออกห่างด้วยสายต่อ\n- **ความชื้นค้างที่ 99 %RH** มีน้ำเกาะที่ตัวตรวจจับ ต้องรอให้แห้งสนิท ตัวเซนเซอร์กันน้ำไม่ได้\n',
